package com.arakaki.prismapdf;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.Build;import android.provider.Settings;import org.json.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;
final class UpdateManager {
 private static final String REPO="cristianoarakaki-cpu/Arakaki",CHANNEL="https://raw.githubusercontent.com/"+REPO+"/main/PrismaPDF/update.json";
 private final MainActivity activity;private boolean working;private File downloaded;
 UpdateManager(MainActivity a){activity=a;}
 private void ui(Runnable r){activity.runOnUiThread(()->{if(!activity.isFinishing()&&!activity.isDestroyed())r.run();});}
 private void message(String title,String text){ui(()->new AlertDialog.Builder(activity).setTitle(title).setMessage(text).setPositiveButton("OK",null).show());}
 private HttpURLConnection connect(String value)throws Exception{URL url=new URL(value);for(int i=0;i<6;i++){if(!activity.online())throw new IOException("Ações online desativadas.");String h=url.getHost();if(!"https".equals(url.getProtocol())||url.getUserInfo()!=null||!(h.equals("github.com")||h.equals("raw.githubusercontent.com")||h.equals("release-assets.githubusercontent.com")||h.equals("objects.githubusercontent.com")))throw new IOException("Destino de atualização inválido.");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","PrismaPDF");int status=c.getResponseCode();if(status>=300&&status<400){String location=c.getHeaderField("Location");c.disconnect();if(location==null)throw new IOException("Redirecionamento inválido.");url=new URL(url,location);continue;}if(status!=200){c.disconnect();throw new IOException("Canal indisponível (HTTP "+status+").");}return c;}throw new IOException("Muitos redirecionamentos.");}
 void check(){if(!activity.online()){activity.notice("Ative as ações online para verificar atualizações.");return;}if(working)return;working=true;activity.notice("Consultando a versão no GitHub…");new Thread(()->{try{HttpURLConnection c=connect(CHANNEL);JSONObject info;try{info=new JSONObject(new String(MainActivity.readLimited(c.getInputStream(),65536),"UTF-8"));}finally{c.disconnect();}if(!activity.getPackageName().equals(info.getString("packageName")))throw new IOException("Canal de outro aplicativo.");int current=activity.getPackageManager().getPackageInfo(activity.getPackageName(),0).versionCode,next=info.getInt("versionCode");if(!info.optBoolean("downloadAvailable",false)||next<=current){activity.notice("Você está usando a versão mais recente disponível.");return;}String url=info.getString("downloadUrl"),sha=info.getString("sha256");if(!url.startsWith("https://github.com/"+REPO+"/releases/download/prisma-v")||!url.endsWith("/Prisma-PDF.apk")||!sha.matches("[a-fA-F0-9]{64}"))throw new IOException("Informações de atualização inválidas.");String notes=info.optString("notes","Melhorias no app.");if(notes.length()>6000)notes=notes.substring(0,6000);final String text=notes;ui(()->new AlertDialog.Builder(activity).setTitle("Prisma PDF "+info.optString("versionName")+" disponível").setMessage(text+"\n\nBaixar esta atualização? O Android pedirá confirmação para instalar.").setPositiveButton("Baixar",(d,w)->download(url,sha,next)).setNegativeButton("Agora não",null).show());}catch(Exception e){message("Não foi possível verificar",e.getMessage());}finally{ui(()->working=false);}}).start();}
 private Set<String> certificates(PackageInfo p)throws Exception{android.content.pm.Signature[] signatures=Build.VERSION.SDK_INT>=28&&p.signingInfo!=null?p.signingInfo.getApkContentsSigners():p.signatures;if(signatures==null||signatures.length==0)throw new IOException("APK sem certificado.");Set<String> result=new HashSet<>();for(android.content.pm.Signature s:signatures)result.add(Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-256").digest(s.toByteArray())));return result;}
 private void download(String url,String sha,int code){if(working)return;working=true;activity.notice("Baixando atualização…");new Thread(()->{File temp=null;try{File dir=new File(activity.getCacheDir(),"exports");dir.mkdirs();temp=new File(dir,"prisma-update.part");HttpURLConnection c=connect(url);MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(temp)){byte[] b=new byte[32768];int n;long total=0;while((n=in.read(b))!=-1){if(!activity.online())throw new IOException("Download interrompido: ações online desativadas.");total+=n;if(total>150L*1024*1024)throw new IOException("APK maior que o limite permitido.");digest.update(b,0,n);out.write(b,0,n);}}finally{c.disconnect();}StringBuilder actual=new StringBuilder();for(byte b:digest.digest())actual.append(String.format(Locale.ROOT,"%02x",b&255));if(!sha.equalsIgnoreCase(actual.toString()))throw new IOException("O arquivo não passou na verificação de integridade.");PackageManager pm=activity.getPackageManager();int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageInfo incoming=pm.getPackageArchiveInfo(temp.getPath(),flags),installed=pm.getPackageInfo(activity.getPackageName(),flags);if(incoming==null||!incoming.packageName.equals(installed.packageName)||incoming.versionCode!=code||incoming.versionCode<=installed.versionCode||!certificates(incoming).equals(certificates(installed)))throw new IOException("Pacote, versão ou assinatura não corresponde ao app instalado.");downloaded=new File(dir,"Prisma-update.apk");if(downloaded.exists()&&!downloaded.delete())throw new IOException("Não foi possível preparar a atualização.");if(!temp.renameTo(downloaded))throw new IOException("Não foi possível preparar a atualização.");ui(()->install());}catch(Exception e){if(temp!=null)temp.delete();message("Atualização não concluída",e.getMessage());}finally{ui(()->working=false);}}).start();}
 void install(){if(downloaded==null||!downloaded.isFile())return;if(!activity.getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(activity).setTitle("Permitir instalação").setMessage("Autorize o Prisma PDF a instalar a atualização na tela do Android. Depois volte ao app.").setPositiveButton("Abrir configurações",(d,w)->activity.startActivityForResult(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())),12)).setNegativeButton("Cancelar",null).show();return;}try{Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(Uri.parse("content://"+activity.getPackageName()+".files/"+downloaded.getName()),"application/vnd.android.package-archive");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);activity.startActivity(i);}catch(Exception e){message("Instalação não iniciada","Não foi possível abrir o instalador do Android.");}}
}
